#!/usr/bin/env bash
# ZONO — apply מסמכים (search + pagination for the document list). macOS-safe.
set -euo pipefail
cd "$(dirname "$0")"
echo "→ repo: $(pwd)"
git am --abort 2>/dev/null || true
git fetch origin
git checkout main
git reset --hard origin/main
cat > /tmp/zono-docs.patch.b64 <<'B64EOF'

B64EOF
base64 -d < /tmp/zono-docs.patch.b64 > /tmp/zono-docs.patch
git am --3way /tmp/zono-docs.patch
echo "→ commit applied:"; git log --oneline -2
git push origin main
echo "✓ pushed. Redeploy will pick up /documents."
